  const responseE1 = await surveysService.ingest({ formID: "assistant-e1", submissionID: "e1-response", answers: [{ questionId: "choice", value: "B" }, { questionId: "scale", value: "Muy de acuerdo" }] });
  assert.equal(responseE1.status, "PENDIENTE_CONFIGURACION");
  assert.equal(await prisma.aggregatedResult.count({ where: { submissionId: responseE1.submissionId } }), 0);
  assert.deepEqual((await surveysService.getDefinitionQuestions(registeredV3.definitionId, actor.sub)).map(question => question.analysisScoring), storedV3Questions.map(question => question.analysisScoring));
  assert.deepEqual(await prisma.coursePublication.findMany({ orderBy: { id: "asc" } }), publicationsBeforeM1);
