  const matrixE2Original = await prisma.submission.findUniqueOrThrow({ where: { id: matrixE2Old.submissionId }, include: { answers: { include: { question: true } } } });
  assert.equal(matrixE2Original.surveyDefinitionId, matrixE2v1.definitionId);
  assert.equal(matrixE2Original.answers.length, 3);
  assert.deepEqual(matrixE2Original.answers.find(answer => answer.question.externalId === "opinions")!.rawValue, matrixE2Raw);
  assert.equal(matrixE2Original.answers.find(answer => answer.question.text === "Protejo especies")!.rawValue, null);
  const nextMatrixE2 = await getSurveySetup("matrix-e2");
