  const nextMatrixSaved = await saveSurveySetup("matrix-e2", { revision: incompleteRowSaved.revision, draft: nextMatrixDraft }, actor);
  assert.equal((await surveysRepository.findActiveDefinition("matrix-e2"))!.id, matrixE2v1.definitionId, "Saving does not activate");
