  const matrixE2v2 = await registerDefinition({ jotformFormId: "matrix-e2", siteId: catalogSite.id, type: "LOCAL", setupRevision: nextMatrixSaved.revision, baseDefinitionId: matrixE2v1.definitionId }, actor.sub);
  const matrixE2v2Definition = await prisma.surveyDefinition.findUniqueOrThrow({ where: { id: matrixE2v2.definitionId } });
