  const matrixE2v2Rows = (await surveysService.getDefinitionQuestions(matrixE2v2.definitionId, actor.sub)).filter(question => (question.sourceContext as any)?.matrix);
  assert.deepEqual(matrixE2v2Rows.map(question => QuestionAnalysisScoringSchema.parse(question.analysisScoring)[0]!.maxScore).sort((a, b) => a! - b!), [3, 20]);
  assert.equal(matrixE2v2Rows.filter(question => question.matrixOverride).length, 1);
  assert.deepEqual((await surveysService.getDefinitionQuestions(matrixE2v1.definitionId, actor.sub)).map(question => question.analysisScoring), matrixE2v1Stored.map(question => question.analysisScoring));
